#include <zephyr/ztest.h>
#include <zephyr/kernel.h>
#include <zephyr/drivers/modem/modem_pipe.h>
#include <zephyr/sys/atomic.h>

#define TEST_PIPE_BUF_SIZE 64

static struct modem_pipe pipe;
static atomic_t test_state;

enum test_modem_pipe_event_bits {
	TEST_MODEM_PIPE_EVENT_OPENED_BIT,
	TEST_MODEM_PIPE_EVENT_CLOSED_BIT,
	TEST_MODEM_PIPE_EVENT_RECEIVE_READY_BIT,
	TEST_MODEM_PIPE_EVENT_TRANSMIT_IDLE_BIT,
	/* Add other bits as needed */
	TEST_MODEM_PIPE_EVENT_COUNT
};

static void modem_pipe_api_callback(struct modem_pipe *pipe, enum modem_pipe_event event, void *user_data)
{
	ARG_UNUSED(pipe);
	ARG_UNUSED(user_data);

	switch (event) {
	case MODEM_PIPE_EVENT_OPENED:
		atomic_set_bit(&test_state, TEST_MODEM_PIPE_EVENT_OPENED_BIT);
		break;
	case MODEM_PIPE_EVENT_CLOSED:
		atomic_set_bit(&test_state, TEST_MODEM_PIPE_EVENT_CLOSED_BIT);
		break;
	case MODEM_PIPE_EVENT_RECEIVE_READY:
		atomic_set_bit(&test_state, TEST_MODEM_PIPE_EVENT_RECEIVE_READY_BIT);
		break;
	case MODEM_PIPE_EVENT_TRANSMIT_IDLE:
		atomic_set_bit(&test_state, TEST_MODEM_PIPE_EVENT_TRANSMIT_IDLE_BIT);
		break;
	default:
		break;
	}
}

/* Test functions */

static void test_pipe_async_open_close(void)
{
	int ret;
	struct modem_pipe_api_config api_cfg = {
		.event_callback = modem_pipe_api_callback,
		.user_data = NULL,
	};

	test_state = 0;

	ret = modem_pipe_open(&pipe, &api_cfg);
	zassert_equal(ret, 0, "modem_pipe_open failed");

	/* Wait for pipe to be opened */
	k_sleep(K_MSEC(100));
	zassert_true(atomic_test_bit(&test_state, TEST_MODEM_PIPE_EVENT_OPENED_BIT),
			"Pipe not opened");

	ret = modem_pipe_close(&pipe);
	zassert_equal(ret, 0, "modem_pipe_close failed");

	/* Wait for pipe to be closed */
	k_sleep(K_MSEC(100));
	zassert_true(atomic_test_bit(&test_state, TEST_MODEM_PIPE_EVENT_CLOSED_BIT),
			"Pipe not closed");
}

static void test_pipe_async_transmit(void)
{
	int ret;
	uint8_t tx_buf[TEST_PIPE_BUF_SIZE];
	struct modem_pipe_api_config api_cfg = {
		.event_callback = modem_pipe_api_callback,
		.user_data = NULL,
	};

	test_state = 0; /* Reset state for this test */

	ret = modem_pipe_open(&pipe, &api_cfg);
	zassert_equal(ret, 0, "modem_pipe_open failed");

	/* Wait for pipe to be opened */
	k_sleep(K_MSEC(100));
	zassert_true(atomic_test_bit(&test_state, TEST_MODEM_PIPE_EVENT_OPENED_BIT),
			"Pipe not opened");

	/* Transmit data */
	ret = modem_pipe_transmit(&pipe, tx_buf, sizeof(tx_buf));
	zassert_equal(ret, 0, "modem_pipe_transmit failed");

	/* Wait for transmit idle event */
	k_sleep(K_MSEC(500));
	/*
	 * The original assertion was: 
	 * zassert_equal(atomic_get(&test_state), BIT(TEST_MODEM_PIPE_EVENT_TRANSMIT_IDLE_BIT),
	 * 		"Transmit idle event not received");
	 * This is incorrect because test_state accumulates bits. If other bits (like OPENED_BIT)
	 * are still set, the equality check will fail. The correct way to check if a specific
	 * bit is set in an atomic accumulator is to use atomic_test_bit.
	 */
	zassert_true(atomic_test_bit(&test_state, TEST_MODEM_PIPE_EVENT_TRANSMIT_IDLE_BIT),
			"Transmit idle event not received");

	ret = modem_pipe_close(&pipe);
	zassert_equal(ret, 0, "modem_pipe_close failed");

	/* Wait for pipe to be closed */
	k_sleep(K_MSEC(100));
	zassert_true(atomic_test_bit(&test_state, TEST_MODEM_PIPE_EVENT_CLOSED_BIT),
			"Pipe not closed");
}

ZTEST_SUITE(modem_pipe, NULL, NULL, NULL, NULL, NULL);

ZTEST(modem_pipe, test_async_open_close)
{
	test_pipe_async_open_close();
}

ZTEST(modem_pipe, test_async_transmit)
{
	test_pipe_async_transmit();
}
